rows.command:
cd /x
export HERMES_HOME=$(mktemp -d)
pytest

python3 - <<'EOF'
if 1 > 0: print(1)
EOF

ssh -qT -p 22 -i ~/.ssh/k -o ConnectTimeout=5 -oBatchMode=yes h sh -s <<'EOS'
{body}
EOS

ssh h 'bash -l -s' <<'EOS'
{body}
EOS

ssh h 'bash -s' <<"EOS"
{body}
EOS

ssh h 'bash -s' <<'EOS'
{body}
EOS

ssh h 'bash -s' <<'EOS' 2>&1 | tail -5
{body}
EOS

ssh h 'bash -s' <<'EOS'; echo done
{body}
EOS

ssh h 'bash -s' <<-'EOS'
	{body}
	EOS

ssh h 'bash -s' <<EOS
echo $(echo x > {core}/f.txt)
EOS

ssh h 'bash -s' <<\EOS
{body}
EOS

ssh h <<'EOS'
{body}
EOS

ssh h bash -ls <<'EOS'
{body}
EOS
